item.description:
melborp server solution for problem running pgadmin container and nginx Configure Nginx: Create a new configuration file for your domain in /etc/nginx/sites-available/melborp.solutions:
nginx
server { listen 80; server_name www.melborp.solutions; location / { proxy_pass http://localhost:8888; # Forward traffic to the pgAdmin container proxy_set_header Host $host; proxy_set_header X-Real-IP $remote_addr; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; proxy_set_header X-Forwarded-Proto $scheme; } }

mijn-bureau-deploy-demo/helmfile/environments/default
adapt /etc/hosts
192.168.0.216 bureaublad.kubernetes.local 192.168.0.216 nextcloud.kubernetes.local 192.168.0.216 id.kubernetes.local 192.168.0.216 matrix.kubernetes.local
&ldquo;global.yaml.gotmpl&rdquo;
allowed values &ldquo;nano&rdquo; &ldquo;micro&rdquo; &ldquo;small&rdquo; &ldquo;medium&rdquo; &ldquo;large&rdquo; &ldquo;xlarge&rdquo; &ldquo;2xlarge&rdquo;
resourcesPreset: &ldquo;small&rdquo; (this as to avoid defining resources for each container)
defaultLocale: &ldquo;nl&rdquo;: Zorgt ervoor dat apps die dit ondersteunen (zoals Nextcloud of Keycloak) direct in het Nederlands opstarten.
hostname: keycloak: &ldquo;id&rdquo; element: &ldquo;element&rdquo; synapse: &ldquo;matrix&rdquo; grist: &ldquo;grist&rdquo; collabora: &ldquo;collabora&rdquo; nextcloud: &ldquo;nextcloud&rdquo; openproject: &ldquo;openproject&rdquo; livekit: &ldquo;livekit&rdquo; meet: &ldquo;meet&rdquo; conversations: &ldquo;conversations&rdquo; docs: &ldquo;docs&rdquo; bureaublad: &ldquo;bureaublad&rdquo; drive: &ldquo;drive&rdquo;
